function CatHouseExploreCell:AddListener()
    SetButtonAction(self.BtnRefresh.gameObject, function()
        local catHouseHomeDojo = CatHouseExploreMgr:GetCatHouseHomeDojo()
        local taskRefreshTimes = checkNumber(catHouseHomeDojo.exploreRefreshTimes)
        local _setBtnInteractiveStatus = function(bool)
            self:SetBtnRefreshTask(bool)
            self:SetBtnOpenTaskEnable(bool)
        end
        local freeRefresh = taskRefreshTimes > 0
        local title = freeRefresh 
                and function()
                    return localize("是否刷新该探险任务?")
                end 
                or function()
                    local goodsId = CatHouseExploreMgr.EXPLORE_REFRESH_GOODS_ID
                    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                    local goodsName = checkString(goodsVo.name)
                    return localize("免费刷新次数不足\n是否消耗_num1_个_num2_立刻刷新该任务?", { _num1_ = checkNumber(CatHouseExploreMgr.EXPLORE_REFRESH_GOODS_NUM), _num2_ = goodsName }) 
                end
        local _funcSure = freeRefresh 
                and function()
                    CatHouseExploreMgr:CatHouseExploreRefresh(self.exploreId, function()
                        self:TaskRefreshShow(function()
                            self:FreshUI(CatHouseExploreMgr:GetExploreData(self.exploreId))
                        end)
                    end)
                    _setBtnInteractiveStatus(true)
                end 
                or function()
                    CatHouseExploreMgr:CatHouseExploreRefreshTimesBuy(function()
                        CatHouseExploreMgr:CatHouseExploreRefresh(self.exploreId, function()
                            self:TaskRefreshShow(function()
                                self:FreshUI(CatHouseExploreMgr:GetExploreData(self.exploreId))
                            end)
                        end)
                    end)
                    _setBtnInteractiveStatus(true)
                end
        local _funcCancel = function()
            _setBtnInteractiveStatus(true)
        end
        _setBtnInteractiveStatus(false)
        GameUtils.SecondConfirm(title(), _funcSure, _funcCancel, nil,nil,nil, true)
    end)
    self:SetEventDrawnReward()
end

