function CatHouseExploreCell:InitComponent()
    local transImgLight = self.Dots:Find("ImgLight")
    if not IsNull(transImgLight) then
        self.siCellLight = KTool.GetComponent(transImgLight.gameObject, typeof(UISwitchImage))
    end
    self.btnRefreshComp = KTool.GetComponent(self.BtnRefresh.gameObject, typeof(Button))
    local transBtnOpenTask = self.controller.transform:Find("AnimRoot/Contnet/Btn")
    if not IsNull(transBtnOpenTask) then
        self.btnOpenTask = KTool.GetComponent(transBtnOpenTask.gameObject, typeof(Button))
    end
    local transTaskCountDown = self.Underway:Find("Time/TextNumber")
    if not IsNull(transTaskCountDown) then
        self.txtTaskCountDown = KTool.GetOrAddComponent(transTaskCountDown.gameObject, typeof(TextMeshProUGUI))
    end

    if not IsNull(self.CanGet) then
        local transIconBox = self.CanGet:Find("Icon/ImgIcon1")
        if not IsNull(transIconBox) then
            self.alterIconBox = KTool.GetOrAddComponent(transIconBox.gameObject, typeof(RawImageAlterable))
        end
        local transIconDiamond = self.CanGet:Find("Icon/ImgIcon2")
        if not IsNull(transIconDiamond) then
            self.goIconDiamond = transIconDiamond.gameObject
        end
    end
end

function CatHouseExploreCell:SetCellInfo(taskData)
    self.taskData = taskData
    local taskQuality = checkInt(taskData.taskQuality)
    local taskSite = checkInt(taskData.site)
    ---任务标题
    local taskName = taskData.taskName
    if not IsNull(self.TitleText) then
        self.TitleText.text = checkString(taskName)
    end
    ---任务星级
    local taskStars = taskData.taskStar
    self:InitTaskStars(taskStars)
    ---任务提供的装备类型
    self.ImgLogo.Status = taskSite
    ---任务底图
    self.ImgMap.Status = taskSite
    self.ImgMap1.Status = taskSite
    self.ImgMap2.Status = taskSite
    self.ImgMap3.Status = taskSite
    self.ImgInk.Status = taskSite
    ---Dots
    if not IsNull(self.siCellLight) then
        self.siCellLight.Status = taskQuality
    end

    if not IsNull(self.alterIconBox) then
        self.alterIconBox:LoadSprite(checkString(taskData.boxPicture))
    end
    if not IsNull(self.goIconDiamond) then
        KTool.SetActive(self.goIconDiamond.gameObject, 
                checkBool(CatHouseExploreMgr:CheckCatsListHadExtraCondition(checkTable(self.exploreData.teamCats), self.exploreId, self.taskId)))
    end
end

function CatHouseExploreCell:CleanStars()
    if self.listStar and #self.listStar > 0 then
        for i = #self.listStar, 1, -1 do
            KTool.SafeDelete(self.listStar[i].gameObject)
            self.listStar[i] = nil
        end
    end
    self.listStar = nil
end

function CatHouseExploreCell:InitTaskStars(stars)
    self:CleanStars()
    if isNull(self.listStar) then self.listStar = {} end
    for i = 1, checkInt(CatHouseExploreMgr.EXPLORE_TASK_STARS_MAX) do
        local go = KTool.Instantiate(self.RootStars.gameObject, self.ImgStar.gameObject)
        table.insert(self.listStar, go)
        if not IsNull(go) then
            KTool.SetActive(go, true)
        end
        local imgSwitch = KTool.GetOrAddComponent(go, typeof(UISwitchImage))
        if not IsNull(imgSwitch) then
            imgSwitch.Status = i <= stars and 2 or 1
        end
    end
end
