function CatHouseExploreCell:SetAnimatorEnabled(bool)
    bool = checkBool(bool)
    if not isNull(self.AnimRoot) then
        if (not bool) and self.coTaskRefreshShow then
            cs_coroutine.stop(self.coTaskRefreshShow)
            self.coTaskRefreshShow = nil
            self:PlayAnimation(LIST_ANIMATION_CELL.Default)
        end
        self.AnimRoot.enabled = bool
    end
end

function CatHouseExploreCell:PlayAnimation(name)
    if not isNull(self.AnimRoot) then
        self:SetAnimatorEnabled(true)
        self.AnimRoot:Play(name,0,0)
        self.AnimRoot:Update(0)
    end
end

function CatHouseExploreCell:TaskRefreshShow(cb)
    self.coTaskRefreshShow = cs_coroutine.start(function()
        self:PlayAnimation(LIST_ANIMATION_CELL.Exit)
        cs_coroutine.yield_return(WaitForSeconds(0.25))
        if cb then cb() end
        self:PlayAnimation(LIST_ANIMATION_CELL.Enter)
        cs_coroutine.yield_return(WaitForSeconds(0.58))
        self.coTaskRefreshShow = nil
    end)
end

function CatHouseExploreCell:FreshUI(exploreData)
    
    if isNull(exploreData) then return end
    ---ArgData
    self.exploreData = exploreData
    self.taskId = exploreData.taskId --taskId_int_任务id
    self.exploreId = exploreData.exploreId --exploreId_int_探险id
    local require = exploreData.require --require_map_k=任务要求条件id，v=要求值
    local teamCats = exploreData.teamCats --teamCats_string_探索猫id，逗号分隔
    local remainTime = exploreData.remainTime --remainTime_int_剩余时间
    print("->CatHouseExploreCell:FreshUI", table.dump(checkTable(exploreData)))
    ---CellInfo
    self.taskData = CatHouseExploreMgr:GetCatHouseTaskData(self.taskId)
    self.taskData.exploreId = exploreData.exploreId
    xTry(function()
        self:SetCellInfo(self.taskData)
        self:RefreshCellStatus(exploreData.status)
    end)
end

function CatHouseExploreCell:RefreshCellStatus(cellStatus)
    if cellStatus == CatHouseExploreMgr.ENUM_TASK_STATUS.NOT_START then
        self:SetCellNotStartStatus()
    elseif cellStatus == CatHouseExploreMgr.ENUM_TASK_STATUS.DURING then
        self:SetCellDuringStatus()
    elseif cellStatus == CatHouseExploreMgr.ENUM_TASK_STATUS.REFRESH_WAIT then
        self:SetCellRefreshWaitStatus()
    elseif cellStatus == CatHouseExploreMgr.ENUM_TASK_STATUS.FINISH then
        self:SetCellFinishStatus()
    end
    self:RefreshRedPoint(cellStatus)
end

function CatHouseExploreCell:SetCellNotStartStatus()
    self:SetEventOpenTask(true)
    KTool.SetActive(self.Normal.gameObject, true)
    KTool.SetActive(self.BtnRefresh.gameObject, true)
    KTool.SetActive(self.RootStars.gameObject, true)
    KTool.SetActive(self.RootTitle.gameObject,true)
    KTool.SetActive(self.Dots.gameObject, true)
    KTool.SetActive(self.ImgMap.gameObject, true)
    
    KTool.SetActive(self.CanGet.gameObject, false)
    KTool.SetActive(self.Underway.gameObject, false)
    
    self:SetDuringTxtStatus(false)
    self:SetBtnOpenTaskEnable(true)
    self:SetBtnRefreshTask(true)
    self:SetTaskTime(self.taskData.taskTime)
end

function CatHouseExploreCell:SetCellDuringStatus()
    self:SetEventOpenTask(false)
    KTool.SetActive(self.Normal.gameObject, false)
    KTool.SetActive(self.BtnRefresh.gameObject, false)
    KTool.SetActive(self.CanGet.gameObject, false)
    KTool.SetActive(self.Underway.gameObject, true)
    KTool.SetActive(self.RootTitle.gameObject,true)
    KTool.SetActive(self.RootStars.gameObject, true)
    KTool.SetActive(self.Dots.gameObject, true)
    KTool.SetActive(self.ImgMap.gameObject, true)
    self:SetDuringTxtStatus(true)
    self:SetBtnOpenTaskEnable(false)
    if not isNull(self.exploreData.timerRemain) then
        self:SetDuringTxtValue(checkNumber(self.exploreData.timerRemain.CountTimes))
        self:SetRemainOnCD(self.exploreData.timerRemain, self.exploreId)
        self.exploreData.timerRemain.OnRemove = function()
            if not isNull(self.controller) then
                local exploreData = CatHouseExploreMgr:GetExploreData(self.exploreId)
                CatHouseExploreMgr:ActionOnRemoveRemain(exploreData)
                self:FreshUI(exploreData)
            end
        end
    end
end

