    self:SetEventOpenTask(false)
    KTool.SetActive(self.Normal.gameObject, false)
    KTool.SetActive(self.BtnRefresh.gameObject, false)
    KTool.SetActive(self.CanGet.gameObject, false)
    KTool.SetActive(self.Underway.gameObject, false)
    KTool.SetActive(self.ImgMap.gameObject, false)
