            if not IsNull(self.controller) then
                local exploreData = CatHouseExploreMgr:GetExploreData(self.exploreId)
                CatHouseExploreMgr:ActionOnRemoveRefreshRemain(exploreData)
                self:FreshUI(exploreData)
            end
        end
    end
end

function CatHouseExploreCell:SetCellFinishStatus()
    self:SetEventOpenTask(false)
    KTool.SetActive(self.Normal.gameObject, false)
    KTool.SetActive(self.BtnRefresh.gameObject, false)
    KTool.SetActive(self.CanGet.gameObject, true)
    KTool.SetActive(self.Underway.gameObject, false)
    KTool.SetActive(self.RootTitle.gameObject,true)
    KTool.SetActive(self.RootStars.gameObject, true)
