function CatHouseExploreCell:SetEventDrawnReward()
    SetButtonAction(self.CanGet.gameObject, function()
        if isNull(self.exploreId) then return end
        
        local exploreBoxId, exploreBoxProgress = CatHouseExploreMgr:GetExploreBoxServicesData()
        local exploreBoxData = CatHouseExploreMgr:GetCatHouseTaskBoxData(exploreBoxId)
        local taskStar = exploreBoxData.star
        print("->CatHouseExploreCell:SetEventDrawnReward:", self.exploreId, checkNumber(exploreBoxProgress / taskStar))
        --if checkNumber(exploreBoxProgress / taskStar) > 1 then
        --    GameUtils.Toast(localize("请先领取探险宝箱"))
        --    return
        --end
        
        self.TaskStatus:Play(string.format("Receive1%d", checkInt(self.exploreId)))
        
        CatHouseExploreMgr:CatHouseExploreEndReq(self.exploreId,function(exploreEndData)
            --- Rewards
            local rewardData = exploreEndData.rewardData
            local taskId = exploreEndData.taskId
            local require = exploreEndData.require

            xTry(function()
                local _playerEXP_GoodId = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 15).num
                local _playerEXP_Num = checkNumber(self.taskData.exp)
                local goodsData = {
                    goodsId = _playerEXP_GoodId,
                    num = _playerEXP_Num }
                --local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
                --playerComponent.playerDojo.mainExp = checkNumber(playerComponent.playerDojo.mainExp) + _playerEXP_Num
                table.insert(rewardData, goodsData)
            end)
            xTry(function()
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewardData, cb =
                function()
                    Events.Broadcast(Constants.EventNames.CloseExpChangeTips)
                end }})
            end)
            --- UpdateCatsData
            local cats = checkTable(CatHouseExploreMgr:GetExploreCatTeam(self.exploreId))
            print("->CatHouseExploreMgr:GetExploreCatTeam", table.dump(cats))
            ---@type ConstantsCatHouse
            local ConstantsCatHouse = import("Game.CatHouse.ConstantsCatHouse")
            ---@type CatHouseComponent
            local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
            for i, cat in pairs(cats) do
                component:UpdateCDData(cat.id, ConstantsCatHouse.CatStatus.Exploring, nil)
            end
            ---BoxStars
            local starsEX = CatHouseExploreMgr:GetExploreBoxStars()
            local starsNow = starsEX + checkNumber(self.taskData.taskStar)
            CatHouseExploreMgr:UpdateExploreBoxStars(starsNow)
            Events.Broadcast(Constants.EventNames.CatHouseExploreBoxStarsUpdate, starsNow)
            ---UpdateExploreTaskData
            local taskDataInMgrNew = {
                exploreId = self.taskData.exploreId,
                taskId = taskId,
                require = require,
                teamCats = {},
                remainTime = 0,
                refreshRemainTime = 0,
                status = CatHouseExploreMgr.ENUM_TASK_STATUS.NOT_START
            }
            CatHouseExploreMgr:SetTaskData(self.exploreId, taskDataInMgrNew)
            self.taskData = CatHouseExploreMgr:GetCatHouseTaskData(taskId)
            self:TaskRefreshShow(function()
                self:SetCellInfo(self.taskData)
            end)
            self:RefreshCellStatus(taskDataInMgrNew.status)
        end)
    end)
end

function CatHouseExploreCell:SetRefreshCountDownTxt(count)
    if not IsNull(self.txtTaskRefreshCountDown) then  
        self.txtTaskRefreshCountDown.text = CfUtils.GetTimeHMS(count)
    end
end

function CatHouseExploreCell:SetDuringTxtValue(value)
    if not IsNull(self.txtTaskCountDown) then
        self.txtTaskCountDown.text = CfUtils.GetTimeHMS(value)
    end
end

function CatHouseExploreCell:SetRemainOnCD(timer, exploreId)
    timer.OnCd = function(count)
        if count <= 0 then   -- 结束
            CatHouseExploreMgr:CleanExploreRemainTimer(exploreId)
            local exploreData = CatHouseExploreMgr:GetExploreData(exploreId)
            CatHouseExploreMgr:ActionOnRemoveRemain(exploreData)
            GameUtils.UpdateServerRedPointData({catHouseExploreTask = 0}) -- 红点
        else
            self:SetDuringTxtValue(count)
        end
    end
end

function CatHouseExploreCell:SetRefreshRemainOnCD(timer, exploreId)
    timer.OnCd = function(count)
        if count <= 0 then   -- 结束
            CatHouseExploreMgr:CleanExploreRefreshRemainTimer(exploreId)
            local exploreData = CatHouseExploreMgr:GetExploreData(exploreId)
            CatHouseExploreMgr:ActionOnRemoveRefreshRemain(exploreData)
        else
            self:SetRefreshCountDownTxt(count)
        end
    end
end

function CatHouseExploreCell:RefreshRedPoint(showStatus)
    local isShow  = checkBool(showStatus == CatHouseExploreMgr.ENUM_TASK_STATUS.FINISH)
    local goRed = GameUtils.GetRedPointGo(self.controller)
    if not IsNull(goRed) then
        KTool.SetActive(goRed, isShow)
    end
end
 
return CatHouseExploreCell